'use strict';
let state=null, loading=false, route='', audioSignature='';
let radioRequest=0, radioPending=null, radioMessage='', radioJobNotice=null;
let receiveFilter=sessionStorage.getItem('meshcore-receive-channel')||'', inboxView=null, inboxAbort=null;
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=v=>Number.isFinite(Number(v))&&v?new Date(v*1000).toLocaleString('de-DE'):'–';
const badge=(label,on=true)=>`<span class="badge ${on?'on':'warn'}">${esc(label)}</span>`;
const metric=(label,value,note)=>`<div class="metric"><span class="metric-label">${esc(label)}</span><strong class="value">${esc(value)}</strong><small>${esc(note)}</small></div>`;
const head=(tag,title,text)=>`<div class="pagehead"><div><span class="eyebrow">${tag}</span><h1>${title}</h1><p>${text}</p></div></div>`;
function radioStations(dab){
 const stations=new Map();
 const add=(service,channel,snr)=>{
  const sid=String(service.sid||'').toLowerCase(),name=String(service.name||'').trim();
  if(!service.audio||!name||!/^0x[0-9a-f]{1,8}$/.test(sid))return;
  if(!stations.has(sid))stations.set(sid,{sid,name,channels:[]});
  const station=stations.get(sid);
  if(!station.channels.some(item=>item.channel===channel))station.channels.push({channel,snr:Number(snr)||0});
 };
 for(const ensemble of dab.inventory?.ensembles||[])for(const service of ensemble.services||[])add(service,ensemble.channel,ensemble.snr);
 if(dab.signal_fresh)for(const service of dab.services||[])add(service,dab.dab_channel,dab.snr);
 return [...stations.values()].sort((a,b)=>a.name.localeCompare(b.name,'de',{sensitivity:'base'}));
}
function asaState(d){
 if(!d.reachable)return {label:'Empfänger nicht erreichbar',note:'Der lokale DAB+-Decoder liefert gerade keine Daten.',kind:'unknown'};
 if(!d.signal_fresh)return {label:'Empfangsdaten nicht aktuell',note:'Das letzte Empfangssignal ist zu alt oder sein Zeitpunkt fehlt. Der Warnstatus ist unbestätigt.',kind:'unknown'};
 if(!d.asa_data_present)return {label:'Keine ASA-Daten verfügbar',note:'DAB+ ist erreichbar; eine ASA-Signalisierung ist noch nicht bestätigt.',kind:'unknown'};
 if(d.asa_active||d.emergency_warning)return {label:d.asa_test?'ASA-Testsignal aktiv':'ASA-Warnsignal aktiv',note:d.asa_test?'Der Decoder kennzeichnet das Signal ausdrücklich als Test.':'Der Decoder meldet ein aktives Warnsignal. Amtliche Hinweise beachten.',kind:d.asa_test?'test':'alert'};
 if(d.asa_outside_area)return {label:'Signal für anderes Zielgebiet',note:'Ein ASA-Signal wird empfangen; der konfigurierte Standort liegt außerhalb des übermittelten Zielgebiets. Keine Weiterleitung nach #warnings.',kind:'normal'};
 return {label:'Kein aktives Warnsignal',note:'Der Empfänger läuft und liefert ASA-Daten. Aktuell meldet der Decoder kein aktives Warnsignal. Das ist keine allgemeine Entwarnung.',kind:'normal'};
}
function overview(){return `<section class="hero"><div><span class="eyebrow">DEIN LOKALES NETZ. AUCH OHNE INTERNET.</span><h1>Dein Funk.<br>Deine Verbindung.</h1><p>MeshCore, DAB+ und dein lokales Nachrichtenarchiv. Direkt auf dem Pi – mit der Pi Console aus deinem GitHub-Projekt.</p><a href="#radio">Funknachricht senden ↗</a></div><div class="meshart" aria-hidden="true"><span class="sat a"></span><span class="sat b"></span><span class="sat c"></span><span class="meshcore">✳</span></div></section><div id="overview-metrics" class="metrics"></div><div class="sectiontitle"><h2>Alles Wichtige im Blick.</h2><small>Live vom Raspberry Pi</small></div><div class="cards"><article class="card"><span class="sourceicon">⌁</span><h3>MeshCore-Funk</h3><p>Empfang und Versand bleiben lokal. Zusätzliche Empfangskanäle werden automatisch erkannt.</p><div class="cardfoot"><span id="radio-card-state"></span><a href="#radio">Öffnen ↗</a></div></article><article class="card"><span class="sourceicon">◉</span><h3>DAB+ & ASA</h3><p id="asa-card-note"></p><div class="cardfoot"><span id="asa-card-state"></span><a href="#asa">Empfang prüfen ↗</a></div></article><article class="card"><span class="sourceicon">♫</span><h3>Deutschlandfunk</h3><p>Die letzten 24 Stunden lokal aufgezeichnet. Vorhandene Aufnahmen brauchen kein Internet.</p><div class="cardfoot"><span id="audio-card-state"></span><a href="#audio">Anhören ↗</a></div></article></div><div class="sectiontitle"><h2>Dein Zugang im Notfall.</h2></div><div class="panel emergency-short"><div><h3>Im selben WLAN bleiben.</h3><p>Internet weg? Dieses Dashboard ist weiter unter der lokalen Pi-Adresse erreichbar. Pi, Funkgerät und Router benötigen Strom.</p></div><a class="button-link" href="#system">Notfallhilfe öffnen ↗</a></div>`;}
function radio(){return head('STATION & FUNK','Hier bist du verbunden.','Ein Funkzugang, ein gemeinsamer Sendetakt. Public bleibt für automatische Bot-Antworten gesperrt.')+`<div id="radio-metrics" class="metrics"></div><section class="panel"><h2>Nachricht über MeshCore senden</h2><p>Die Nachricht wird lokal vorgemerkt. „Vom Funkgerät angenommen“ bestätigt die Annahme durch dein Gerät, nicht den Empfang bei anderen.</p><form id="send-form"><div class="fields"><label>Kanal<select id="send-channel" required></select></label><label>Verfügbare Länge<span id="byte-count" class="byte-count">0 / 110 Bytes</span><small>Umlaute und Emojis benötigen mehrere Bytes.</small></label></div><label class="message-label">Nachricht<textarea id="send-text" rows="4" required placeholder="Deine Nachricht an den gewählten Kanal"></textarea></label><div class="send-row"><button class="primary" id="send-button">In Funkwarteschlange ↗</button><span id="send-result" role="status"></span></div></form></section><section class="panel"><h2>Eingerichtete Empfangskanäle</h2><p>Empfang ist von der Antwortberechtigung des Bots getrennt. Der lokale Nachrichtensender verwendet weiterhin nur die freigegebenen Kanäle.</p><div id="channel-list" class="channel-list"></div></section><section class="panel"><h2>Letzte lokale Sendungen</h2><div id="radio-outbox"></div></section>`;}
function reception(){return head('EMPFANG & VERSAND','Du siehst, was ankommt.','Die letzten empfangenen Texte und lokalen Sendungen. Der App-Verlauf wird bei einem Serverausfall zwischengespeichert.')+`<div id="receive-metrics" class="metrics"></div><section class="panel"><h2>Lokaler Funkempfang</h2><div class="receive-filter"><label>Kanal anzeigen<select id="receive-channel" aria-describedby="receive-filter-help"><option value="">Alle Kanäle</option></select></label><p id="receive-filter-help">Bis zu 100 Nachrichten der letzten 24 Stunden. Die Auswahl bleibt in dieser Sitzung erhalten.</p></div><div id="receive-list"></div></section><section class="panel"><h2>Lokaler Nachrichtenausgang</h2><div id="receive-outbox"></div></section><section class="panel"><h2>Bot-Antworten · Paketstatus</h2><div id="packet-counts" class="channel-list"></div><p>„Angenommen“ bezieht sich auf die lokale Funkannahme. Nach einem unklaren oder fehlgeschlagenen Antwortteil werden die restlichen Teile angehalten.</p></section>`;}
function asa(){return head('DAB+ ASA · LOKALER EMPFANG','Warnungen verstehen.','Empfangsbereitschaft und ein aktives Warnsignal sind zwei verschiedene Zustände.')+`<section class="panel"><h2>Radiosender auswählen</h2><p>Wähle deinen Sender direkt nach Namen. Die passende Frequenz wird automatisch eingestellt.</p><a class="button-link" href="#audio">Radio hören ↗</a><details><summary>Empfangstechnik (optional)</summary><h3>DAB+-Ensemble auswählen</h3><div class="fields"><label>Ensemble / Frequenz<select id="dab-channel"></select></label><div><button type="button" id="dab-retune" class="primary">Empfänger umschalten ↗</button><p id="dab-tune-state" role="status"></p></div></div><div class="note amber">Ein Empfänger, ein Ensemble: Während du andere Ensembles empfängst, wird 5C nicht überwacht. Für die stündlichen DLF-Nachrichten schaltet der Pi automatisch um und danach zurück. Vorhandene Aufnahmen bleiben erhalten.</div><div id="dab-services" class="channel-list"></div></details></section><section class="panel"><div class="sectiontitle"><h2>Empfangbare Sender & Ensembles</h2><button id="dab-scan" type="button">Band III durchsuchen ↻</button></div><p>Der Suchlauf prüft alle 38 DAB+-Blöcke und speichert gefundene Programme lokal. Währenddessen sind kontinuierlicher Warnempfang und neue DLF-Aufnahmen unterbrochen. Danach wird der bisherige Kanal wiederhergestellt.</p><p id="dab-scan-status" role="status"></p><div id="dab-inventory"></div><div class="note">ASA wird pro Ensemble signalisiert und gilt für dessen Programme. „Nachgewiesen“ bedeutet empfangene ASA/EWS-Signalisierung. „Nicht nachgewiesen“ beweist keine fehlende Unterstützung; schwache oder vorübergehend fehlende Signale können beim Suchlauf unbestätigt bleiben.</div></section><section id="asa-banner" class="asa-banner" aria-live="polite"></section><div id="asa-metrics" class="metrics"></div><div class="grid2"><section class="panel"><h2>Dein DAB+-Empfänger</h2><div class="receiver"><div class="sdr" aria-hidden="true">NOOELEC · RTL-SDR</div><div><h3>Terrestrisch verbunden.</h3><p><span id="dab-receiver-note">Ensemble und Signalwerte kommen direkt vom lokalen Decoder.</span></p></div></div><dl id="asa-receiver" class="status-list"></dl></section><section class="panel"><h2>Was bedeutet der ASA-Status?</h2><p><b>ASA-Daten vorhanden:</b> Der Decoder liefert ASA-Informationen.</p><p><b>Kein aktives Warnsignal:</b> Empfang läuft, aktuell wird kein Warnsignal gemeldet. Das ist kein Defekt und keine allgemeine Entwarnung.</p><p><b>Warnsignal oder Test aktiv:</b> Die Art wird anhand der Decoder-Daten ausdrücklich angezeigt. Veraltete Daten gelten als unbestätigt.</p></section></div><section class="panel"><h2>Weiterleitung über Funk</h2><label class="toggle"><span>ASA-Warnsignale automatisch nach #warnings<small>Nur reale, aktuelle Signale. Testsignale werden verworfen; Wiederholungen werden unterdrückt.</small></span><input id="asa-forward" type="checkbox"></label><div id="asa-forward-note" class="note" role="status"></div><p>Der Decoder liefert bislang Signalisierungsdaten, keinen amtlichen Warntext. Über Funk wird deshalb ausdrücklich ein empfangenes ASA-Warnsignal gemeldet. Es werden keine Gefahrenbeschreibung und keine Entwarnung erfunden.</p><p>Internet ist für diesen lokalen DAB+-Empfang und die Anzeige nicht erforderlich.</p></section><section class="panel"><details><summary>Technische Signalisierung anzeigen</summary><dl id="asa-details" class="status-list"></dl><p>Decoder-Status und Signalisierungslevel sind Rohwerte. Sie werden hier nicht als amtliche Gefahrenstufe interpretiert.</p></details></section><section class="panel"><h2>Journaline</h2><div id="journaline"></div></section>`;}
function audio(){return head('DAB+ · LIVE UND LOKALES ARCHIV','Radio zum Anhören.','Sender wählen, einschalten und aufnehmen. Mehrere Sender derselben Empfangsfrequenz können parallel laufen.')+`<section class="panel radio-studio"><h2>Live-Radio</h2><div class="fields"><label for="live-station">Sender<select id="live-station"></select></label><div><button id="live-start" class="primary">Sender einschalten</button></div></div><p id="live-state" role="status"></p><p id="live-listeners"></p><div id="radio-decks"></div><p class="radio-help">Bis zu 16 Wiedergaben. Für parallele Sender muss der gemeinsame Empfänger dieselbe Frequenz verwenden. Senderwechsel und stündliche DLF-Nachrichten können andere Sender unterbrechen. Mehr Vorpufferung sorgt für ruhigere Wiedergabe, mit einigen Sekunden Verzögerung.</p></section><section class="panel"><h2>Deine Radioaufnahmen</h2><p>1, 5 oder 15 Minuten aufnehmen und jederzeit stoppen. Aufnahmen bleiben bis zu 24 Stunden lokal auf dem Pi.</p><div id="radio-recordings"></div></section><div class="sectiontitle"><h2>Deutschlandfunk · Nachrichtenarchiv</h2></div><div id="audio-summary" class="note"></div><div id="audio-list" class="recordings"></div>`;}



function system(){return head('NOTFALL & SYSTEM','Dein Zugang bleibt lokal.','Diese Seiten werden vollständig vom Pi geladen. Es gibt keine externen Schriftarten, Skripte oder Online-Anmeldung.')+`<div class="panel"><h2>Internet weg? So kommst du hinein.</h2><div class="steps"><div class="step"><span class="num">01 / VERBINDEN</span><b>Im lokalen WLAN bleiben</b><p>Handy oder Computer mit demselben Router verbinden. Internet ist dafür nicht nötig.</p></div><div class="step"><span class="num">02 / ÖFFNEN</span><b>Pi-Adresse aufrufen</b><p><a href="http://192.168.8.200:8091/">http://192.168.8.200:8091</a><br><a href="http://marc-desktop.local:8091/">http://marc-desktop.local:8091</a></p></div><div class="step"><span class="num">03 / FUNKEN</span><b>Nachricht lokal senden</b><p>Unter „Funk & Kanäle“ einen freigegebenen Kanal wählen und die Funkannahme prüfen.</p></div></div><div class="note amber">Pi, Funkgerät und Router/WLAN benötigen Strom. Diese Einrichtung ist kein eigener WLAN-Hotspot und überbrückt keinen Stromausfall.</div><a class="button-link" href="/notfall">Kompakte Notfallanleitung ↗</a></div><div class="grid2"><section class="panel"><h2>Ohne Internet verfügbar</h2><ul class="feature-list"><li>Lokale Funknachrichten senden und empfangen</li><li>Ping, Funkkürzel, Rechnen und Memory-Befehle</li><li>DAB+- und ASA-Empfang anzeigen; reale ASA-Signale nach #warnings weiterleiten</li><li>Vorhandene DLF-Aufnahmen abspielen</li></ul><p>Aktuelle Wetterdaten benötigen Internet. Ein eingerichtetes KI-Handy kann bei einem Ausfall kurze lokale Bot-Antworten übernehmen. Lokale Funkannahme garantiert keinen Empfang bei anderen.</p></section><section class="panel"><h2>Geschützte Konfiguration</h2><p>Die Konfigurationsoberfläche aus dem GitHub-Projekt bleibt über einen lokalen SSH-Tunnel geschützt:</p><pre>ssh -L 8765:127.0.0.1:8765 marc@192.168.8.200</pre><p>Danach <code>http://127.0.0.1:8765</code> öffnen. Keine Router-Portfreigabe erforderlich.</p></section></div><section class="panel"><h2>Laufende Dienste</h2><div id="service-list"></div><details><summary>Sicherung und Wiederherstellung</summary><p>Programmcode und Installationspakete liegen lokal auf dem Pi. Auch eine Neuinstallation aus dem bereitgelegten Paketbestand kann ohne Internet erfolgen.</p><p>Die Wiederherstellungsanleitung liegt geschützt unter <code>/var/backups/meshcore-pi-v04/README.txt</code>. Sicherungen enthalten vertrauliche Einstellungen und bleiben lokal geschützt.</p></details></section>`;}
let phoneCSRF='',phoneLive=false,phoneTimer=null,phoneAbort=null,phoneURL='',phoneGesture=null,phoneGeneration=0,phoneNativeFullscreen=false;
function phone(){return head('MOTOROLA · PER USB AM PI','Dein Handy. Direkt bedienbar.','Status prüfen, Bildschirm ansehen und das Motorola aus der Ferne bedienen.')+`<section class="panel"><h2>Geschützter Zugang</h2><p>Über <a href="http://100.110.16.69:8091/#phone">Tailscale öffnen</a>. Im Notfall funktioniert auch ein lokaler SSH-Tunnel. Nutze deinen festen Zugangscode oder fordere einen Einmalcode am Motorola an.</p><p id="phone-message" role="status">Verbindung wird geprüft …</p><div id="phone-pair"><button id="phone-request">Code am Handy anzeigen</button><form id="phone-auth"><label>Zugangscode<input id="phone-code" type="password" inputmode="numeric" autocomplete="current-password" pattern="[0-9]{4,12}" maxlength="12" required></label><button class="primary">Diesen Browser freigeben</button></form><p>Die Freigabe gilt sieben Tage. Das Handy wird nicht automatisch entsperrt.</p></div><div id="phone-connected" hidden><div id="phone-metrics" class="metrics"></div><button id="phone-live" class="primary">Livebild einschalten</button> <button id="phone-logout">Browser abmelden</button><p>Bild antippen oder darüber wischen. Gesprächston und Mikrofon separat unter „Telefonieren“ verbinden. Bilder werden nicht gespeichert. Geschützte Apps können schwarz bleiben.</p><div id="phone-view" class="phone-view"><div class="phone-viewbar"><button id="phone-fullscreen" type="button">Vollbild öffnen ⛶</button><small>Tippen und Wischen funktionieren auch im Vollbild. Mit Esc oder dem Knopf wieder schließen.</small></div><div class="phone-layout"><div class="phone-display"><img id="phone-screen" alt="Livebild des Motorola" hidden draggable="false"><p id="phone-screen-note">Livebild ist ausgeschaltet.</p></div><div class="phone-controls">${phoneAudioMarkup()}<h3>Fernbedienung</h3><div class="phone-keypad"><button data-phone-key="wake">Display an</button><button data-phone-key="sleep">Display aus</button><button data-phone-key="back">Zurück</button><button data-phone-key="home">Home</button><button data-phone-key="recent">Offene Apps</button><button data-phone-key="volume_up">Lauter</button><button data-phone-key="volume_down">Leiser</button></div><form id="phone-text-form"><label>Text ins gewählte Eingabefeld<input id="phone-text" maxlength="300" autocomplete="off"></label><button>Text eingeben</button><small>Ohne automatisches Absenden. Umlaute bitte über die Bildschirmtastatur eingeben.</small></form><p>Zum Entsperren das Handy verwenden. Keine Geräte-PIN im Dashboard speichern.</p></div></div></div></div></section>`;}
async function phoneAPI(path,data){
 const response=await fetch('/api/phone/'+path,{method:data===undefined?'GET':'POST',cache:'no-store',headers:{'Content-Type':'application/json','X-Phone-CSRF':phoneCSRF},...(data===undefined?{}:{body:JSON.stringify(data)})});
 const result=await response.json();if(!response.ok)throw Error(result.error||'Handy-Verbindung fehlgeschlagen');return result;
}
function phoneMessage(message){if(route==='phone'&&$('#phone-message'))$('#phone-message').textContent=message;}
function stopPhone(){closePhoneFullscreen();phoneGeneration++;phoneLive=false;clearTimeout(phoneTimer);if(phoneAbort)phoneAbort.abort();phoneAbort=null;if(phoneURL)URL.revokeObjectURL(phoneURL);phoneURL='';const img=$('#phone-screen');if(img){img.hidden=true;img.removeAttribute('src');}if($('#phone-live'))$('#phone-live').textContent='Livebild einschalten';if($('#phone-screen-note')){$('#phone-screen-note').hidden=false;$('#phone-screen-note').textContent='Livebild ist ausgeschaltet.';}}
function closePhoneFullscreen(){
 const view=$('#phone-view');phoneNativeFullscreen=false;view?.classList.remove('phone-expanded');document.body.classList.remove('phone-fullscreen-open');if($('#phone-fullscreen'))$('#phone-fullscreen').textContent='Vollbild öffnen ⛶';if(view&&document.fullscreenElement===view)document.exitFullscreen().catch(()=>{});
}
async function togglePhoneFullscreen(){
 const view=$('#phone-view');if(!view)return;if(view.classList.contains('phone-expanded')){closePhoneFullscreen();return;}
 view.classList.add('phone-expanded');document.body.classList.add('phone-fullscreen-open');$('#phone-fullscreen').textContent='Vollbild schließen ✕';if(!phoneLive){phoneLive=true;$('#phone-live').textContent='Livebild ausschalten';phoneFrame();}
 // Embedded browsers may reject native fullscreen; the full-window view remains usable.
 if(view.requestFullscreen){try{await view.requestFullscreen();phoneNativeFullscreen=true;}catch(error){phoneNativeFullscreen=false;}}
}
document.addEventListener('fullscreenchange',()=>{if(phoneNativeFullscreen&&document.fullscreenElement!==$('#phone-view'))closePhoneFullscreen();});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&$('#phone-view')?.classList.contains('phone-expanded'))closePhoneFullscreen();});
async function phoneFrame(){
 const generation=phoneGeneration;if(!phoneLive||route!=='phone'||document.hidden)return;
 const controller=new AbortController();phoneAbort=controller;const timeout=setTimeout(()=>controller.abort(),15000);
 try{const response=await fetch('/api/phone/frame',{cache:'no-store',headers:{'X-Phone-CSRF':phoneCSRF},signal:controller.signal});if(!response.ok){const data=await response.json();throw Error(data.error||'Livebild fehlt');}const blob=await response.blob();if(generation!==phoneGeneration||route!=='phone')return;const old=phoneURL;phoneURL=URL.createObjectURL(blob);const img=$('#phone-screen');img.src=phoneURL;img.hidden=false;$('#phone-screen-note').hidden=true;if(old)URL.revokeObjectURL(old);}
 catch(error){if(generation===phoneGeneration){stopPhone();phoneMessage(error.name==='AbortError'?'Livebild unterbrochen; bitte erneut einschalten.':error.message);}}
 finally{clearTimeout(timeout);if(phoneAbort===controller)phoneAbort=null;if(generation===phoneGeneration&&phoneLive)phoneTimer=setTimeout(phoneFrame,1100);}
}
async function phoneControl(data){try{await phoneAPI('control',data);phoneMessage('Aktion ausgeführt.');}catch(error){phoneMessage(error.message);}}
async function initPhone(){
 initPhoneAudio();
 const generation=phoneGeneration;
 $('#phone-request').onclick=async()=>{try{phoneMessage((await phoneAPI('pair',{})).message);}catch(error){phoneMessage(error.message);}};
 $('#phone-auth').onsubmit=async event=>{event.preventDefault();try{await phoneAPI('authorize',{code:$('#phone-code').value});$('#phone-code').value='';await initPhone();}catch(error){phoneMessage(error.message);}};
 $('#phone-logout').onclick=async()=>{await stopPhoneAudio();stopPhone();try{await phoneAPI('logout',{});phoneCSRF='';await initPhone();}catch(error){phoneMessage(error.message);}};
 $('#phone-fullscreen').onclick=togglePhoneFullscreen;
 $('#phone-live').onclick=()=>{if(phoneLive)stopPhone();else{phoneLive=true;$('#phone-live').textContent='Livebild ausschalten';phoneFrame();}};
 document.querySelectorAll('[data-phone-key]').forEach(button=>button.onclick=()=>phoneControl({action:'key',key:button.dataset.phoneKey}));
 $('#phone-text-form').onsubmit=async event=>{event.preventDefault();await phoneControl({action:'text',text:$('#phone-text').value});$('#phone-text').value='';};
 const img=$('#phone-screen');
 const point=event=>{const box=img.getBoundingClientRect();return {x:Math.max(0,Math.min(img.naturalWidth-1,Math.floor((event.clientX-box.left)*img.naturalWidth/box.width))),y:Math.max(0,Math.min(img.naturalHeight-1,Math.floor((event.clientY-box.top)*img.naturalHeight/box.height)))};};
 img.onpointerdown=event=>{if(!phoneLive||!img.naturalWidth)return;phoneGesture={...point(event),at:Date.now()};img.setPointerCapture(event.pointerId);event.preventDefault();};
 img.onpointercancel=()=>phoneGesture=null;
 img.onpointerup=event=>{if(!phoneGesture||!phoneLive)return;const start=phoneGesture,end=point(event);phoneGesture=null;const moved=Math.hypot(start.x-end.x,start.y-end.y)>25;phoneControl(moved?{action:'swipe',x:start.x,y:start.y,x2:end.x,y2:end.y,duration:Math.min(2000,Math.max(100,Date.now()-start.at))}:{action:'tap',x:end.x,y:end.y});};
 try{const session=await phoneAPI('session');if(route!=='phone'||generation!==phoneGeneration)return;phoneCSRF=session.csrf||'';$('#phone-pair').hidden=!!session.authorized;$('#phone-connected').hidden=!session.authorized;phoneMessage(session.authorized?'Dieser Browser ist freigegeben bis '+time(session.expires)+'.':'Mit Zugangscode freigeben oder Einmalcode am Handy anfordern.');if(session.authorized){refreshPhoneAudio();const info=await phoneAPI('status');if(route!=='phone'||generation!==phoneGeneration)return;$('#phone-metrics').innerHTML=metric('GERÄT',info.model,'Android '+info.android)+metric('AKKU',info.battery===null?'–':info.battery+' %',info.charging?'Wird geladen':'Akkubetrieb')+metric('TEMPERATUR',info.temperature===null?'–':info.temperature+' °C','Vom Handy gemeldet');}}
 catch(error){phoneMessage(error.message);}
}
document.addEventListener('visibilitychange',()=>{if(document.hidden)stopPhone();});

const pages={overview,radio,reception,asa,audio,phone,system};
function navigate(){stopPhoneAudio();stopPhone();radioRequest++;radioPending=null;radioMessage='';radioJobNotice=null;const next=location.hash.slice(1)||'overview';route=pages[next]?next:'overview';$('#main').innerHTML=pages[route]();document.querySelectorAll('nav a').forEach(a=>{const active=a.hash==='#'+route;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});audioSignature='';window.scrollTo(0,0);if(route==='radio'){$('#send-form').addEventListener('submit',send);$('#send-text').addEventListener('input',updateBytes);}if(route==='asa'){$('#dab-scan').addEventListener('click',startScan);$('#dab-retune').addEventListener('click',()=>saveDab({channel:$('#dab-channel').value}));$('#asa-forward').addEventListener('change',()=>saveDab({forward_asa:$('#asa-forward').checked}));}if(route==='audio'){$('#live-start').addEventListener('click',playRadio);$('#live-station').addEventListener('change',event=>sessionStorage.setItem('meshcore-radio-station',event.target.value));}if(route==='reception')$('#receive-channel').addEventListener('change',event=>{receiveFilter=event.target.value;sessionStorage.setItem('meshcore-receive-channel',receiveFilter);inboxView=null;renderReception();refreshInbox();});if(route==='phone')initPhone();if(state)update();}
const statuses={queued:'Wartet',sending:'Wird gesendet',accepted:'Vom Funkgerät angenommen',failed:'Fehlgeschlagen',uncertain:'Funkannahme unklar',cancelled:'Abgebrochen',expired:'Abgelaufen',mirrored:'An App weitergegeben'};
function statusName(s){return statuses[s]||({'local_queued':'Vom lokalen Bot angenommen','local_ignored':'Empfangen, keine Bot-Antwort','local_limited':'Bot-Limit erreicht'})[s]||s;}
function outbox(items){return items.length?`<div class="table-wrap"><table><thead><tr><th>Zeit / Kanal</th><th>Nachricht</th><th>Status</th></tr></thead><tbody>${items.map(m=>`<tr><td>${esc(time(m.created))}<small>${esc(m.channel)}</small></td><td class="message-cell">${esc(m.text)}</td><td>${badge(statusName(m.status),m.status==='accepted')}</td></tr>`).join('')}</tbody></table></div>`:'<p class="empty">Noch keine lokalen Sendungen.</p>';}
function received(items){return items.length?items.map(m=>`<article class="received-row"><div><strong>${esc(m.channel)}</strong><small>${esc(time(m.received))} · ${esc(statusName(m.state))}</small></div><p>${esc(m.text)}</p></article>`).join(''):'<p class="empty">Noch keine empfangenen Nachrichten im lokalen Verlauf.</p>';}
function update(){
 const d=state,b=d.bot,x=d.dab,a=asaState(x),channels=Array.isArray(b.channels)?b.channels:[];
 $('#live-status').textContent=b.connected?'Pi verbunden · Funk aktiv':'Pi erreichbar · Funkstatus prüfen';$('#updated').textContent='Aktualisiert '+time(d.now);
 if(route==='overview'){
  $('#overview-metrics').innerHTML=metric('FUNKVERBINDUNG',b.connected?'Verbunden':'Unbestätigt','Bot '+b.version+' · lokal auf deinem Pi')+metric('EMPFANGSKANÄLE',channels.length||'–','Alle eingerichteten Kanäle')+metric('DAB+ EMPFANG',x.signal_fresh?'Aktiv':'Prüfen',(x.ensemble||'Kein Ensemble').trim())+metric('LOKALES ARCHIV',d.recordings.length,'DLF-Aufnahmen · letzte 24 Stunden');
  $('#radio-card-state').innerHTML=badge(b.connected?'Lokal aktiv':'Status prüfen',b.connected);$('#asa-card-note').textContent=a.note;$('#asa-card-state').innerHTML=badge(a.kind==='normal'?'Empfang aktiv':a.label,a.kind==='normal');$('#audio-card-state').innerHTML=badge(d.recordings.length+' Aufnahmen');
 }else if(route==='radio'){
  $('#radio-metrics').innerHTML=metric('LOKALER BOT',b.connected?'Aktiv':'Unbestätigt','Version '+b.version)+metric('EMPFANGSKANÄLE',channels.length||'–','Vom Funkgerät eingerichtet')+metric('REPEATER',b.repeaters??'–','Lokal gespeicherter Bestand')+metric('STATUSALTER',b.age==null?'–':b.age+' s','Heartbeat des lokalen Bots');
  if(!$('#send-channel').options.length)$('#send-channel').innerHTML=d.channels.map(c=>`<option>${esc(c)}</option>`).join('');$('#channel-list').innerHTML=channels.length?channels.map(c=>`<span class="channel-chip">${esc(c)}${['Public','#public'].includes(c)?' · Bot stumm':''}</span>`).join(''):'<p>Kanalliste wird vom Gateway aktualisiert.</p>';$('#radio-outbox').innerHTML=outbox(d.outbox);
 }else if(route==='reception'){renderReception();refreshInbox();
 }else if(route==='asa'){
  $('#asa-banner').className='asa-banner '+a.kind;$('#asa-banner').innerHTML=`<span class="eyebrow">${x.signal_fresh?'LIVE VOM DECODER':'STATUS UNBESTÄTIGT'}</span><h2>${esc(a.label)}</h2><p>${esc(a.note)}</p>`;
  $('#asa-metrics').innerHTML=metric('EMPFANG',x.signal_fresh?'Aktiv':'Unbestätigt',x.dab_channel||'5C')+metric('SIGNAL / SNR',typeof x.snr==='number'?x.snr+' dB':'–','Direkt vom DAB+-Decoder')+metric('ASA-DATEN',x.asa_data_present?'Vorhanden':'Unbestätigt','Empfang ist von Warnaktivität getrennt')+metric('FUNKWEITERLEITUNG',x.asa_forwarding?'Bereit':x.asa_forwarding_requested?'Wartet':'Aus','#warnings · nur reale Signale');
  const channelSelect=$('#dab-channel'),found=x.inventory?.ensembles||[],optionSignature=JSON.stringify([found,x.presets]);if(channelSelect.dataset.signature!==optionSignature){const selected=channelSelect.value||x.desired_channel;channelSelect.innerHTML=(found.length?`<optgroup label="Empfangene Ensembles">${found.map(e=>`<option value="${esc(e.channel)}">${esc(e.name)} · ${esc(e.channel)} · ${esc(e.frequency_mhz)} MHz</option>`).join('')}</optgroup>`:'')+`<optgroup label="Weitere Blöcke · Empfang nicht bestätigt">${x.presets.filter(p=>!found.some(e=>e.channel===p.channel)).map(p=>`<option value="${esc(p.channel)}">${esc(p.name)} · ${esc(p.channel)} · ${esc(p.frequency_mhz)} MHz</option>`).join('')}</optgroup>`;channelSelect.value=selected;channelSelect.dataset.signature=optionSignature;}
  $('#dab-tune-state').textContent=x.dab_channel===x.desired_channel?'Empfängt '+x.dab_channel+(x.dab_channel==='5C'?' · DLF verfügbar':' · stündlich automatisch DLF'):'Umschaltung angefordert: '+x.desired_channel+' · aktuell '+(x.dab_channel||'unbestätigt');
  const scan=x.scan||{},inventory=x.inventory||{ensembles:[]};$('#dab-scan').disabled=!!scan.running||x.scan_allowed===false;$('#dab-retune').disabled=!!scan.running;$('#asa-forward').disabled=!!scan.running;
  $('#dab-scan-status').textContent=scan.running?'Suchlauf: Block '+(scan.channel||'wird vorbereitet')+' · '+(scan.index||0)+' / '+(scan.total||38)+' · '+(scan.found||0)+' Ensembles gefunden':scan.error?'Suchlauf unterbrochen: '+scan.error:inventory.checked_at?'Letzter Suchlauf: '+time(inventory.checked_at)+(inventory.complete?' · vollständig':' · bisherige Teilergebnisse'):'Noch kein vollständiger Suchlauf gespeichert.';if(!scan.running&&x.scan_allowed===false)$('#dab-scan-status').textContent+=' Nachrichten-Aufnahmen haben Vorrang; bitte später erneut suchen.';
  const inventoryNode=$('#dab-inventory'),signature=JSON.stringify(inventory);if(inventoryNode.dataset.signature!==signature){inventoryNode.dataset.signature=signature;inventoryNode.innerHTML=(inventory.ensembles||[]).map(e=>{const programmes=(e.services||[]).filter(s=>s.audio!==false);return `<article class="panel ensemble"><div class="ensemble-head"><div><h3>${esc(e.name)}</h3><p>${esc(e.channel)} · ${esc(e.frequency_mhz)} MHz · SNR ${esc(e.snr??'–')} dB</p></div><button data-dab-tune="${esc(e.channel)}">Empfangen ↗</button></div><div class="ensemble-meta">${badge(e.asa_observed?'ASA nachgewiesen':'ASA unbestätigt',e.asa_observed)}<span>${programmes.length} Radioprogramme · geprüft ${esc(time(e.checked_at))}</span></div><details><summary>Radioprogramme anzeigen</summary><div class="channel-list">${programmes.map(s=>`<span class="channel-chip">${esc(s.name||s.sid)}</span>`).join('')||'<p>Keine benannten Radioprogramme erkannt.</p>'}</div></details></article>`;}).join('')||'<p>Noch keine Ensemble-Liste vorhanden. Starte einen Suchlauf, um alle aktuell empfangbaren Programme aufzunehmen.</p>';inventoryNode.querySelectorAll('[data-dab-tune]').forEach(button=>button.addEventListener('click',()=>saveDab({channel:button.dataset.dabTune})));}inventoryNode.querySelectorAll('button').forEach(button=>button.disabled=!!scan.running);
  $('#dab-services').innerHTML=x.services.map(s=>`<span class="channel-chip">${esc(s.name||s.sid)}</span>`).join('')||'<p>Noch keine Programme im ausgewählten Ensemble erkannt.</p>';
  if(!$('#asa-forward').disabled)$('#asa-forward').checked=x.asa_forwarding_requested;
  $('#asa-forward-note').textContent=x.asa_forwarding?'Weiterleitung nach #warnings bereit. Nur reale, aktuelle ASA-Warnsignale des gewählten Ensembles werden automatisch vorgemerkt.':x.asa_forwarding_requested?'Weiterleitung ist eingeschaltet; aktueller Status: '+({awaiting_validated_signal:'wartet auf geprüfte Signalisierung',unverified_decoder:'Decoder nicht verifiziert',test_suppressed:'Testsignal unterdrückt',outside_area:'Signal für anderes Zielgebiet',blocked:'Kanalregel sperrt die Weiterleitung',retuning:'Empfänger schaltet um',receiver_unavailable:'Empfänger nicht erreichbar'}[b.asa_forward_status]||'wird geprüft')+'.':'Automatische ASA-Weiterleitung ist ausgeschaltet.';
  $('#dab-receiver-note').textContent='DAB+-Kanal '+(x.dab_channel||'unbestätigt')+' · Live-Daten des lokalen Decoders.';
  $('#asa-receiver').innerHTML=`<dt>Ensemble</dt><dd>${esc((x.ensemble||'–').trim())}</dd><dt>Empfangsdienst</dt><dd>${esc(d.services['ideenwerft-dab-monitor.service']==='active'?'Läuft':'Status prüfen')}</dd><dt>Empfangsdaten</dt><dd>${x.frame_age_seconds==null?'Zeitpunkt fehlt':esc(x.frame_age_seconds)+' s alt'}</dd><dt>EWS-Ensemble</dt><dd>${x.ews_ensemble?'Vom Decoder bestätigt':'Nicht bestätigt'}</dd>`;
  $('#asa-details').innerHTML=`<dt>Decoder-Status</dt><dd>${esc(x.asa_status||'–')}</dd><dt>Signalisierungslevel</dt><dd>${esc(x.asa_level??'–')}</dd><dt>Testkennzeichnung</dt><dd>${x.asa_test?'Ja':'Nein'}</dd><dt>Letzte Signaländerung</dt><dd>${esc(time(x.asa_changed_at))}</dd>`;$('#journaline').innerHTML=x.journaline.length?x.journaline.map(i=>`<article class="received-row"><h3>${esc(i.title||'Journaline')}</h3><p>${esc(i.body||'')}</p></article>`).join(''):'<p>Aktuell keine lokalen Journaline-Texte vorhanden.</p>';
 }else if(route==='audio'){
  const stationSelect=$('#live-station'),stations=radioStations(x),stationSignature=JSON.stringify(stations.map(s=>[s.sid,s.name]));
  if(stationSelect.dataset.signature!==stationSignature){const selected=stationSelect.value||sessionStorage.getItem('meshcore-radio-station');stationSelect.innerHTML=stations.map(s=>`<option value="${esc(s.sid)}">${esc(s.name)}</option>`).join('');if(stations.some(s=>s.sid===selected))stationSelect.value=selected;stationSelect.dataset.signature=stationSignature;}
  stationSelect.disabled=!!radioPending;$('#live-start').disabled=!!x.scan?.running||!stations.length||!!radioPending;$('#live-start').textContent=radioPending?'Empfang wird vorbereitet …':'Sender einschalten';
  $('#live-listeners').textContent=(d.radio?.listeners||0)+' aktive Wiedergaben · bis zu '+(d.radio?.limit||16)+' gleichzeitig';
  $('#live-state').textContent=radioMessage||(x.scan?.running?'Sendersuchlauf läuft; Radio pausiert.':x.rbb_news_window?'Die Berlin-Nachrichten von rbb 88.8 werden gerade aufgenommen.':x.news_window?'Die Deutschlandfunk-Nachrichten haben gerade Vorrang.':stations.length?'Wähle einen Sender und drücke „Sender einschalten“.':'Noch keine Sender gefunden. Unter DAB+ ASA einen Sendersuchlauf starten.');
  renderRadioStudio(d);
  $('#audio-summary').textContent=d.recordings.length+' lokale Aufnahmen · Die Audiodateien bleiben auf dem Pi. Während der Wiedergabe wird der Player nicht neu geladen.';const signature=d.recordings.map(r=>r.file).join('|');if(signature!==audioSignature){const playing=[...document.querySelectorAll('audio')].some(player=>!player.paused);if(!playing){$('#audio-list').innerHTML=d.recordings.map(r=>`<article class="panel recording"><div class="recording-top"><span class="sourceicon">♫</span><div><h2>Deutschlandfunk · ${esc(r.time)} Uhr</h2><p>${Math.round(r.bytes/1048576)} MB · lokal gespeichert</p></div></div><audio controls preload="none" aria-label="DLF-Aufnahme ${esc(r.time)}" src="/audio/${encodeURIComponent(r.file)}"></audio></article>`).join('')||'<section class="panel"><p>Noch keine Aufnahme im 24-Stunden-Fenster.</p></section>';audioSignature=signature;}}
 }else if(route==='system'){$('#service-list').innerHTML=Object.entries(d.services).map(([k,v])=>`<div class="service-row"><span>${esc(({'meshcore-gateway.service':'MeshCore-Gateway','ideenwerft-dab-monitor.service':'DAB+ / ASA-Empfang','ideenwerft-dab-news.service':'DLF-Aufzeichnung und Nachrichten','ideenwerft-rbb-news.timer':'Nachrichten: ungerade Stunden rbb 88.8 · gerade DLF','meshcore-dashboard.service':'Geschützte Konfigurationsoberfläche'})[k]||k)}</span>${badge(v==='active'?'Läuft':v,v==='active')}</div>`).join('');const phone=d.phone_ai;if(phone?.state){const ready=phone.state==='ready'&&d.now-phone.checked_at>=-5&&d.now-phone.checked_at<45;const label=ready?'Lokal bereit':phone.state==='loading'?'Modell lädt':'Handyverbindung prüfen';$('#service-list').innerHTML+=`<div class="service-row"><span>Offline-KI auf Motorola · ${esc(phone.model)}</span>${badge(label,ready)}</div>`;}}
}
function renderReception(){
 if(route!=='reception'||!state)return;
 const d=state,b=d.bot,ib=inboxView||(receiveFilter?null:d.inbox),select=$('#receive-channel');
 const channels=[...new Set([...(b.channels||[]),...(d.inbox.channels||[]),...(inboxView?.channels||[]),...(receiveFilter?[receiveFilter]:[])])];
 const options='<option value="">Alle Kanäle</option>'+channels.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');
 if(select.dataset.options!==options){select.innerHTML=options;select.dataset.options=options;}select.value=receiveFilter;
 const total=Object.values(ib?.counts||{}).reduce((v,n)=>v+Number(n),0);
 $('#receive-metrics').innerHTML=metric(receiveFilter?'EMPFANGEN · '+receiveFilter:'EMPFANGEN · ALLE KANÄLE',ib?total:'…','Letzte 24 Stunden · aktueller Filter')+metric('LOKALER AUSGANG',d.outbox.length,'Bis zu 20 letzte Sendungen')+metric('BOT-PAKETE',Object.values(b.packets).reduce((v,n)=>v+Number(n),0),'Alle gespeicherten Paketstatus')+metric('APP-SERVER',d.remote.state==='online'?'Erreichbar':d.remote.state==='checking'?'Wird geprüft':'Offline','Lokaler Empfang bleibt aktiv');
 $('#receive-list').innerHTML=!ib?'<p>Nachrichten werden geladen …</p>':ib.error?'<p>Der gefilterte Verlauf konnte gerade nicht aktualisiert werden. Erneut aktualisieren.</p>':ib.available?received(ib.latest):'<p>Lokaler Funkverlauf gerade nicht verfügbar.</p>';
 $('#receive-outbox').innerHTML=outbox(d.outbox);
 $('#packet-counts').innerHTML=Object.entries(b.packets).map(([k,v])=>`<span class="channel-chip">${esc(statusName(k))}: ${esc(v)}</span>`).join('')||'<p>Noch keine Bot-Antwortpakete gespeichert.</p>';
}
async function refreshInbox(){
 if(route!=='reception')return;
 if(inboxAbort)inboxAbort.abort();const controller=new AbortController();inboxAbort=controller;
 const filter=receiveFilter,timeout=setTimeout(()=>controller.abort(),6000);
 try{const response=await fetch('/api/inbox?'+new URLSearchParams({channel:filter}),{cache:'no-store',signal:controller.signal});if(!response.ok)throw Error('Verlauf nicht verfügbar');const data=await response.json();if(route==='reception'&&filter===receiveFilter&&inboxAbort===controller){inboxView=data;renderReception();}}
 catch(error){if(inboxAbort===controller&&route==='reception'&&filter===receiveFilter){inboxView={error:true};renderReception();}}
 finally{clearTimeout(timeout);if(inboxAbort===controller)inboxAbort=null;}
}

function updateBytes(){const count=new TextEncoder().encode($('#send-text').value).length;$('#byte-count').textContent=count+' / 110 Bytes';$('#byte-count').classList.toggle('too-long',count>110);$('#send-button').disabled=count>110||count===0;}
async function send(event){event.preventDefault();const button=$('#send-button'),result=$('#send-result');button.disabled=true;result.textContent='Wird lokal vorgemerkt …';try{const response=await fetch('/api/send',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({channel:$('#send-channel').value,text:$('#send-text').value})});const data=await response.json();if(!response.ok)throw Error(data.error||'Senden fehlgeschlagen');$('#send-text').value='';updateBytes();result.textContent='In der lokalen Funkwarteschlange. Den Status siehst du unten.';await load();}catch(error){result.textContent=error.message;updateBytes();}}
async function startScan(){
 const button=$('#dab-scan');button.disabled=true;
 try{const response=await fetch('/api/dab/scan',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});const result=await response.json();if(!response.ok)throw Error(result.error||'Suchlauf nicht verfügbar');$('#dab-scan-status').textContent='Suchlauf gestartet. Fortschritt und Ergebnisse werden automatisch aktualisiert.';await load();}
 catch(error){$('#dab-scan-status').textContent=error.message;button.disabled=false;}
}

async function saveDab(settings){
 const button=$('#dab-retune'),toggle=$('#asa-forward');button.disabled=true;toggle.disabled=true;
 try{const response=await fetch('/api/dab/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(settings)});const result=await response.json();if(!response.ok)throw Error(result.error||'DAB-Einstellung fehlgeschlagen');$('#dab-tune-state').textContent=settings.channel?'Umschaltung auf '+settings.channel+' angefordert. Der Empfänger übernimmt die Auswahl in wenigen Sekunden.':'ASA-Einstellung gespeichert.';if(settings.channel)$('#dab-channel').value=settings.channel;await load();}
 catch(error){$('#dab-tune-state').textContent=error.message;}
 finally{button.disabled=false;toggle.disabled=false;}
}

async function load(){if(loading)return;loading=true;const abort=new AbortController(),timeout=setTimeout(()=>abort.abort(),7000);try{const response=await fetch('/api/status',{cache:'no-store',signal:abort.signal});if(!response.ok)throw Error('Status nicht verfügbar');state=await response.json();$('#connection-error').hidden=true;update();}catch(error){$('#connection-error').textContent='Die Verbindung zum Pi fehlt gerade. Angezeigte Werte können veraltet sein. Lokales WLAN prüfen und erneut aktualisieren.';$('#connection-error').hidden=false;$('#live-status').textContent='Pi-Verbindung prüfen';}finally{clearTimeout(timeout);loading=false;}}
window.addEventListener('hashchange',navigate);$('#refresh').addEventListener('click',load);navigate();load();setInterval(()=>{load();if(route==='phone'&&phoneCSRF)initPhone();},10000);

async function playRadio(){
 const station=radioStations(state.dab).find(s=>s.sid===$('#live-station').value);
 if(!station||radioPending)return;
 const request=++radioRequest;let player=null;
 const choices=station.channels.slice().sort((a,b)=>b.snr-a.snr);
 const target=choices.find(c=>c.channel===state.dab.dab_channel)?.channel||choices[0].channel;
 radioJobNotice=null;radioPending=station.sid;radioMessage=station.name+' wird vorbereitet …';update();

 try{
  if(state.dab.scan?.running)throw Error('Der Sendersuchlauf läuft. Bitte danach erneut starten.');
  if(state.dab.rbb_news_window&&target!=='7D')throw Error('rbb 88.8 Berlin-Nachrichten haben bis Minute 05:50 Vorrang. Bitte danach erneut starten.');
  if(state.dab.news_window&&target!=='5C')throw Error('Deutschlandfunk-Nachrichten haben bis Minute 05:50 Vorrang. Bitte danach erneut „Sender einschalten“ drücken.');
  if(state.dab.dab_channel!==target||state.dab.desired_channel!==target){
   const response=await fetch('/api/dab/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({channel:target})});
   const result=await response.json();if(!response.ok)throw Error(result.error||'Sender konnte nicht eingestellt werden.');
  }
  const deadline=Date.now()+30000;let ready=false;
  while(Date.now()<deadline){
   if(request!==radioRequest||route!=='audio')return;
   const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),7000);
   try{
    const response=await fetch('/api/status',{cache:'no-store',signal:controller.signal});
    if(!response.ok)throw Error('Pi-Status gerade nicht verfügbar.');
    const latest=await response.json();
    if(request!==radioRequest||route!=='audio')return;
    state=latest;update();const dab=latest.dab;
    if(dab.scan?.running)throw Error('Sendersuchlauf gestartet. Bitte danach erneut versuchen.');
    if(dab.rbb_news_window&&target!=='7D')throw Error('Die rbb 88.8 Berlin-Nachrichten beginnen. Bitte ab Minute 05:50 erneut starten.');
    if(dab.news_window&&target!=='5C')throw Error('Die Deutschlandfunk-Nachrichten beginnen. Bitte ab Minute 05:50 erneut starten.');
    if(dab.desired_channel!==target)throw Error('Die Senderauswahl wurde auf einem anderen Gerät geändert. Bitte erneut starten.');
    if(dab.dab_channel===target&&dab.signal_fresh&&dab.services.some(s=>s.audio&&s.sid===station.sid)){ready=true;break;}
   }finally{clearTimeout(timeout);}
   await new Promise(resolve=>setTimeout(resolve,1000));
  }
  if(!ready)throw Error('Der Sender ist gerade nicht empfangsbereit. Bitte erneut versuchen.');
  player=radioDeck(station,target);
  if(player.paused||player.readyState===0){player.src='/radio/'+station.sid;}
  try{await player.play();if(request!==radioRequest||route!=='audio')return;radioMessage=station.name+' läuft.';}
  catch(error){if(error.name==='NotAllowedError')radioMessage=station.name+' ist bereit. Zum Hören die Wiedergabetaste im Player drücken.';else throw Error('Audio noch nicht verfügbar. Bitte erneut „Sender einschalten“ drücken.');}
 }catch(error){if(request===radioRequest&&route==='audio')radioMessage=error.message;}
 finally{if(request===radioRequest&&route==='audio'){radioPending=null;update();}}
}

function radioDeck(station,channel){
 let deck=$('#radio-decks').querySelector(`[data-radio-sid="${station.sid}"]`);
 if(!deck){
  deck=document.createElement('article');deck.className='radio-deck';deck.dataset.radioSid=station.sid;
  deck.innerHTML=`<div class="deck-heading"><h2>${esc(station.name)}</h2><button data-close aria-label="${esc(station.name)} ausschalten">Ausschalten</button></div><div class="song-display"><span data-song>Sendertext wird empfangen …</span><small data-match></small></div><audio controls preload="auto" aria-label="${esc(station.name)} live"></audio><div class="deck-actions"><label>Aufnahmedauer<select data-duration><option value="60">1 Minute</option><option value="300" selected>5 Minuten</option><option value="900">15 Minuten</option></select></label><button data-record>● Aufnahme</button><button data-identify>♫ Song online erkennen</button></div><small>Senderinfos werden lokal angezeigt. Online-Erkennung fragt Shazam mit einem ca. 12 Sekunden langen Audio-Fingerabdruck ab; Internet nötig, nur auf Klick.</small>`;
  $('#radio-decks').append(deck);
  deck.querySelector('[data-close]').addEventListener('click',()=>{const audio=deck.querySelector('audio');audio.pause();audio.removeAttribute('src');audio.load();deck.remove();});
  deck.querySelector('[data-record]').addEventListener('click',()=>radioJob('record',{sid:station.sid,seconds:Number(deck.querySelector('[data-duration]').value)}));
  deck.querySelector('[data-identify]').addEventListener('click',()=>radioJob('identify',{sid:station.sid}));
 }
 deck.dataset.channel=channel;return deck.querySelector('audio');
}
async function radioJob(action,data){
 try{const response=await fetch('/api/radio/'+action,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});const result=await response.json();if(!response.ok)throw Error(result.error||'Auftrag fehlgeschlagen');radioJobNotice=['delete','restore'].includes(action)?null:result.id;radioMessage=action==='delete'?'Aufnahme im Papierkorb.':action==='restore'?'Aufnahme wiederhergestellt.':action==='identify'?'Songerkennung gestartet. Der Treffer erscheint beim Sender.':action==='stop'?'Aufnahme wird abgeschlossen.':'Aufnahme gestartet. Du kannst sie unten stoppen.';await load();return result;}
 catch(error){radioMessage=error.message;if(state)update();return null;}
}
function renderRadioStudio(d){
 const jobs=d.radio?.jobs||[];
 const completed=radioJobNotice?jobs.find(j=>j.id===radioJobNotice):null;
 if(completed&&!radioPending&&['ready','matched','no_match','failed','interrupted'].includes(completed.status)){
  radioMessage=completed.status==='ready'?'Aufnahme gespeichert. Du kannst sie unten anhören oder herunterladen.':completed.status==='matched'?'Song erkannt: '+completed.result.artist+' — '+completed.result.title:completed.status==='no_match'?'Kein Song erkannt. Du kannst es später erneut versuchen.':completed.error||'Auftrag wurde unterbrochen.';
  $('#live-state').textContent=radioMessage;radioJobNotice=null;
 }

 $('#radio-decks').querySelectorAll('[data-radio-sid]').forEach(deck=>{
  const service=d.dab.services.find(s=>s.sid===deck.dataset.radioSid),same=deck.dataset.channel===d.dab.dab_channel;
  deck.querySelector('[data-song]').textContent=!same?'Empfang wurde auf einen anderen Senderbereich umgestellt.':service?.song?.text||'Der Sender übermittelt gerade keine aktuelle Titelinfo.';
  const recognition=jobs.find(j=>j.kind==='identify'&&j.sid===deck.dataset.radioSid);
  deck.querySelector('[data-match]').textContent=!recognition?'':recognition.status==='matched'?'Online-Treffer: '+recognition.result.artist+' — '+recognition.result.title+' · '+time(recognition.finished):recognition.status==='no_match'?'Online: kein Song erkannt.':recognition.status==='failed'?recognition.error:['preparing','capturing','recognizing'].includes(recognition.status)?'Online-Erkennung läuft …':'';
 });
 const node=$('#radio-recordings'),signature=JSON.stringify(jobs);
 if(node.dataset.signature!==signature&&![...node.querySelectorAll('audio')].some(a=>!a.paused)){
  node.dataset.signature=signature;
  node.innerHTML=jobs.filter(j=>j.kind==='record'&&j.status!=='deleted').map(j=>`<article class="recording panel"><h3>${esc(j.station||'Radioaufnahme')} · ${esc(time(j.created))}</h3><p>${esc(({preparing:'Wird vorbereitet',capturing:'Aufnahme läuft',ready:'Gespeichert',failed:'Fehlgeschlagen',interrupted:'Unterbrochen'})[j.status]||j.status)} · ${(j.bytes/1048576).toFixed(1)} MB ${j.error?' · '+esc(j.error):''}</p>${['preparing','capturing'].includes(j.status)?`<button data-stop-recording="${j.id}">■ Aufnahme stoppen</button>`:''}${j.file?`<audio controls preload="none" src="/radio-recordings/${encodeURIComponent(j.file)}"></audio><a href="/radio-recordings/${encodeURIComponent(j.file)}" download>MP3 herunterladen ↗</a><button data-delete-recording="${j.id}">Aufnahme löschen</button>`:''}</article>`).join('')||'<p>Noch keine eigenen Radioaufnahmen vorhanden.</p>';const deleted=jobs.filter(j=>j.kind==='record'&&j.status==='deleted');if(deleted.length)node.innerHTML+=`<details><summary>Papierkorb (${deleted.length})</summary><p>Wiederherstellen ist innerhalb der regulären 24-Stunden-Aufbewahrung möglich.</p>${deleted.map(j=>`<p>${esc(j.station||'Radioaufnahme')} · ${esc(time(j.created))} <button data-restore-recording="${j.id}">Wiederherstellen</button></p>`).join('')}</details>`;
  node.querySelectorAll('[data-delete-recording]').forEach(button=>button.addEventListener('click',async()=>{const row=button.closest('article'),audio=row.querySelector('audio');if(audio){audio.pause();audio.removeAttribute('src');audio.load();}const result=await radioJob('delete',{id:button.dataset.deleteRecording});if(result)row.remove();}));
  node.querySelectorAll('[data-restore-recording]').forEach(button=>button.addEventListener('click',()=>radioJob('restore',{id:button.dataset.restoreRecording})));
  node.querySelectorAll('[data-stop-recording]').forEach(button=>button.addEventListener('click',()=>radioJob('stop',{id:button.dataset.stopRecording})));
 }
}
